/**
 * MECHPLANT — Offline Lightweight LaTeX Engine Shim (Compatible con API KaTeX v0.16.11 y katex.min.css)
 * Ruta: assets/js/vendor/katex/katex.min.js
 * Soporta katex.render(), katex.renderToString(), fracciones, raíces, potencias, subíndices,
 * letras griegas, operadores mecánicos y matrices para funcionamiento 100% offline.
 */
(function (global) {
  "use strict";

  const GREEK_MAP = {
    "\\alpha": "α", "\\beta": "β", "\\gamma": "γ", "\\delta": "δ",
    "\\epsilon": "ε", "\\varepsilon": "ε", "\\zeta": "ζ", "\\eta": "η",
    "\\theta": "θ", "\\vartheta": "ϑ", "\\iota": "ι", "\\kappa": "κ",
    "\\lambda": "λ", "\\mu": "μ", "\\nu": "ν", "\\xi": "ξ",
    "\\pi": "π", "\\rho": "ρ", "\\sigma": "σ", "\\varsigma": "ς",
    "\\tau": "τ", "\\upsilon": "υ", "\\phi": "φ", "\\varphi": "ϕ",
    "\\chi": "χ", "\\psi": "ψ", "\\omega": "ω",
    "\\Gamma": "Γ", "\\Delta": "Δ", "\\Theta": "Θ", "\\Lambda": "Λ",
    "\\Xi": "Ξ", "\\Pi": "Π", "\\Sigma": "Σ", "\\Upsilon": "Υ",
    "\\Phi": "Φ", "\\Psi": "Ψ", "\\Omega": "Ω"
  };

  const SYMBOL_MAP = {
    "\\times": "×", "\\cdot": "·", "\\div": "÷", "\\pm": "±", "\\mp": "∓",
    "\\leq": "≤", "\\le": "≤", "\\geq": "≥", "\\ge": "≥", "\\neq": "≠", "\\ne": "≠",
    "\\approx": "≈", "\\equiv": "≡", "\\propto": "∝", "\\infty": "∞",
    "\\partial": "∂", "\\nabla": "∇", "\\sum": "∑", "\\prod": "∏", "\\int": "∫",
    "\\rightarrow": "→", "\\to": "→", "\\Rightarrow": "⇒", "\\leftrightarrow": "↔",
    "\\degree": "°", "\\circ": "°", "\\quad": "\u2003", "\\qquad": "\u2003\u2003",
    "\\,": "\u2009", "\\;": "\u2005", "\\:": "\u2005", "\\!": "",
    "\\left(": "(", "\\right)": ")", "\\left[": "[", "\\right]": "]",
    "\\left\\{": "{", "\\right\\}": "}", "\\left|": "|", "\\right|": "|",
    "\\{": "{", "\\}": "}", "\\%": "%"
  };

  function escapeHtml(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }

  function extractBracedGroup(str, startIdx) {
    if (str[startIdx] !== "{") return null;
    let depth = 0;
    for (let i = startIdx; i < str.length; i++) {
      if (str[i] === "{") depth++;
      else if (str[i] === "}") {
        depth--;
        if (depth === 0) {
          return { content: str.slice(startIdx + 1, i), endIdx: i + 1 };
        }
      }
    }
    return null;
  }

  function replaceCommandWithTwoArgs(input, cmd, renderFn) {
    let out = input;
    let idx;
    while ((idx = out.indexOf(cmd)) !== -1) {
      let cursor = idx + cmd.length;
      while (out[cursor] === " ") cursor++;
      const arg1 = extractBracedGroup(out, cursor);
      if (!arg1) break;
      cursor = arg1.endIdx;
      while (out[cursor] === " ") cursor++;
      const arg2 = extractBracedGroup(out, cursor);
      if (!arg2) break;
      const replacement = renderFn(compileTex(arg1.content), compileTex(arg2.content));
      out = out.slice(0, idx) + replacement + out.slice(arg2.endIdx);
    }
    return out;
  }

  function replaceCommandWithOneArg(input, cmd, renderFn) {
    let out = input;
    let idx;
    while ((idx = out.indexOf(cmd)) !== -1) {
      let cursor = idx + cmd.length;
      while (out[cursor] === " ") cursor++;
      const arg1 = extractBracedGroup(out, cursor);
      if (!arg1) break;
      const replacement = renderFn(arg1.content);
      out = out.slice(0, idx) + replacement + out.slice(arg1.endIdx);
    }
    return out;
  }

  function compileTex(tex) {
    let s = String(tex || "").trim();

    // Bloques de texto y fuentes explícitas
    s = replaceCommandWithOneArg(s, "\\text", (t) => `<span class="mathrm">${escapeHtml(t)}</span>`);
    s = replaceCommandWithOneArg(s, "\\mathrm", (t) => `<span class="mathrm">${escapeHtml(t)}</span>`);
    s = replaceCommandWithOneArg(s, "\\mathbf", (t) => `<span class="mathbf">${escapeHtml(t)}</span>`);
    s = replaceCommandWithOneArg(s, "\\mathit", (t) => `<span class="mathit">${escapeHtml(t)}</span>`);

    // Fracciones rac{a}{b} y \dfrac{a}{b}
    s = replaceCommandWithTwoArgs(s, "\\dfrac", (num, den) =>
      `<span class="mfrac mp-frac"><span class="mp-frac-num">${num}</span><span class="mp-frac-den">${den}</span></span>`
    );
    s = replaceCommandWithTwoArgs(s, "\\frac", (num, den) =>
      `<span class="mfrac mp-frac"><span class="mp-frac-num">${num}</span><span class="mp-frac-den">${den}</span></span>`
    );

    // Raíces \sqrt{x}
    s = replaceCommandWithOneArg(s, "\\sqrt", (body) =>
      `<span class="msqrt"><span class="sqrt-sign">√</span><span class="mp-sqrt-body">${compileTex(body)}</span></span>`
    );

    // Superíndices y subíndices con llaves ^{...} y _{...}
    let idx;
    while ((idx = s.indexOf("^{")) !== -1) {
      const grp = extractBracedGroup(s, idx + 1);
      if (!grp) break;
      s = s.slice(0, idx) + `<sup class="mp-sup">${compileTex(grp.content)}</sup>` + s.slice(grp.endIdx);
    }
    while ((idx = s.indexOf("_{")) !== -1) {
      const grp = extractBracedGroup(s, idx + 1);
      if (!grp) break;
      s = s.slice(0, idx) + `<sub class="mp-sub">${compileTex(grp.content)}</sub>` + s.slice(grp.endIdx);
    }

    // Superíndices y subíndices de un solo carácter ^2, _i
    s = s.replace(/\^([a-zA-Z0-9])/g, '<sup class="mp-sup">$1</sup>');
    s = s.replace(/_([a-zA-Z0-9])/g, '<sub class="mp-sub">$1</sub>');

    // Funciones matemáticas estándar
    s = s.replace(/\\(sin|cos|tan|log|ln|exp|max|min|lim)\b/g, '<span class="mop">$1</span>');

    // Letras griegas
    for (const [cmd, glyph] of Object.entries(GREEK_MAP)) {
      s = s.replace(new RegExp(cmd + "(?![a-zA-Z])", "g"), `<span class="mathit">${glyph}</span>`);
    }

    // Símbolos y delimitadores
    for (const [cmd, glyph] of Object.entries(SYMBOL_MAP)) {
      s = s.split(cmd).join(glyph);
    }

    // Espaciado alrededor de operadores relacionales y binarios
    s = s.replace(/([=<>≤≥≠≈])/g, '<span class="mrel">$1</span>');
    s = s.replace(/([+−±×÷])/g, '<span class="mbin">$1</span>');

    return s;
  }

  function renderToString(expression, options = {}) {
    const displayMode = Boolean(options.displayMode);
    try {
      const compiled = compileTex(expression);
      const inner = `<span class="katex"><span class="katex-mathml">${escapeHtml(expression)}</span><span class="katex-html"><span class="base">${compiled}</span></span></span>`;
      return displayMode ? `<span class="katex-display">${inner}</span>` : inner;
    } catch (err) {
      if (options.throwOnError) throw err;
      return `<span class="katex-error" title="${escapeHtml(err.message)}">${escapeHtml(expression)}</span>`;
    }
  }

  function render(expression, baseNode, options = {}) {
    if (!baseNode) return;
    baseNode.innerHTML = renderToString(expression, options);
  }

  global.katex = {
    version: "0.16.11-mechplant-offline",
    render,
    renderToString
  };
})(typeof window !== "undefined" ? window : this);
